previewCss:
.darma-loader-darma-b14-honey-drip { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #fde047); width: calc(var(--loader-size, 108px) * .68); height: var(--loader-size, 108px); position: relative; }
.darma-loader-darma-b14-honey-drip::before { content: ''; position: absolute; top: 0; left: 8%; width: 84%; height: 17%; border-radius: 4px 4px 42% 42%; background: linear-gradient(var(--accent-2), var(--accent)); }
.darma-loader-darma-b14-honey-drip::after { content: ''; position: absolute; bottom: 0; left: 12%; width: 76%; height: 13%; border-radius: 50% 50% 6px 6px; background: var(--accent); animation: darma-loader-darma-b14-honey-drip-pool calc(var(--loader-speed, 1s) * 1.9) ease-in-out infinite; }
.darma-loader-darma-b14-honey-drip span { position: absolute; top: 15%; left: 45%; width: 10%; height: 19%; border-radius: 50% 50% 62% 62%; background: linear-gradient(var(--accent), color-mix(in srgb, #fff 20%, var(--accent-2))); animation: darma-loader-darma-b14-honey-drip-ooze calc(var(--loader-speed, 1s) * 1.9) ease-in infinite; }
.darma-loader-darma-b14-honey-drip span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .95); }
@keyframes darma-loader-darma-b14-honey-drip-ooze { 0% { opacity: 0; transform: translateY(0) scaleY(.4); } 12% { opacity: 1; } 45% { transform: translateY(122%) scaleY(1.9); } 78% { transform: translateY(288%) scaleY(1); } 100% { opacity: 0; transform: translateY(340%) scaleY(.5); } }
@keyframes darma-loader-darma-b14-honey-drip-pool { 0%, 100% { transform: scaleX(1); } 50% { transform: scaleX(1.08); } }

